func main() {
	// 获取当前目录
	dir, err := os.Getwd()
	if err != nil {
		log.Fatal(err)
	}

	// 创建文件系统观察者
	fsWatcher, err := fsnotify.NewWatcher()
	if err != nil {
		log.Fatal(err)
	}
	defer fsWatcher.Close()

	// 创建文件系统观察者
	fsWatcher.AddRecursive(dir)

	// 创建文件系统事件通道
	events, err := fsWatcher.Events()
	if err != nil {
		log.Fatal(err)
	}

	// 创建文件系统事件处理函数
	fsWatcher.OnEvent(func(event fsnotify.Event) {
		// 处理文件系统事件
		if event.Op&fsnotify.Write == fsnotify.Write {
			// 文件被修改，执行构建和测试
			buildAndTest()
		}
	})

	// 启动文件系统观察者
	fsWatcher.Start()

	// 等待文件系统事件
	for {
		select {
		case event := <-events:
			if event.Op == fsnotify.Write {
				// 文件被修改，执行构建和测试
				buildAndTest()
			}
		}
	}
}

